package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.records.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.core.type.TypeReference;
import tools.jackson.databind.ObjectMapper;
import static com.fitnutri.backend.records.workout.ExerciseEntryInputs.*;
/** Stored dated snapshots only. Reads do not call current weight or estimate services. */
@Service @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class WorkoutSnapshotReader{
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final CanonicalV2Json canonical;
 public WorkoutSnapshotReader(JdbcTemplate jdbc,ObjectMapper json,CanonicalV2Json canonical){this.jdbc=jdbc;this.json=json;this.canonical=canonical;}
 public record Root(String id,long version,LocalDate recordDate,String source,Instant createdAt,Instant updatedAt,Entry input,WorkoutEstimateService.Response preview){}
 public record State(Root root,Map<String,Object>row,List<Map<String,Object>>periods,Map<Long,List<Map<String,Object>>>movements,Map<UUID,WorkoutEstimateService.HistoricalPeriod> historical){}
 public Root detailForReuse(Long owner,String kind,long id){return state(owner,kind,id).root();}
 public State state(Long owner,String kind,long id){var roots=jdbc.queryForList("SELECT * FROM "+table(kind)+" WHERE user_id=? AND id=? AND deleted_at IS NULL"+(kind.equals("quick")?" AND workout_id IS NULL":""),owner,id);if(roots.isEmpty())throw missing();var row=roots.getFirst();var periodRows=kind.equals("quick")?List.of(row):jdbc.queryForList("SELECT * FROM exercise_record WHERE user_id=? AND workout_id=? AND deleted_at IS NULL ORDER BY period_position,id",owner,id);var moveRows=kind.equals("quick")?jdbc.queryForList("SELECT m.* FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=? AND e.id=? AND e.deleted_at IS NULL ORDER BY m.position,m.id",owner,id):jdbc.queryForList("SELECT m.* FROM workout_movement_log m JOIN exercise_record e ON e.id=m.exercise_record_id WHERE e.user_id=? AND e.workout_id=? AND e.deleted_at IS NULL ORDER BY e.period_position,m.position,m.id",owner,id);var moves=new HashMap<Long,List<Map<String,Object>>>();for(var m:moveRows)moves.computeIfAbsent(((Number)m.get("exercise_record_id")).longValue(),key->new ArrayList<>()).add(m);
  return fromRows(kind,id,row,periodRows,moves);
 }
 State fromRows(String kind,long id,Map<String,Object>row,List<Map<String,Object>>periodRows,Map<Long,List<Map<String,Object>>>moves){
  var ps=new ArrayList<Period>();var summaries=new ArrayList<WorkoutEstimateService.PeriodPreview>();var historical=new HashMap<UUID,WorkoutEstimateService.HistoricalPeriod>();BigDecimal minutes=BigDecimal.ZERO,energy=BigDecimal.ZERO.setScale(3);int available=0;
  for(var p:periodRows){if(p.get("exercise_option_id")==null)throw new BusinessException(HttpStatus.CONFLICT,"CONTRACT_UPGRADE_REQUIRED","Use the original activity correction flow or explicitly select a reviewed exercise option.");long periodId=((Number)p.get("id")).longValue();var movements=moves.getOrDefault(periodId,List.of());var inputMoves=movements.stream().map(m->new Movement(m.get("movement_catalogue_id").toString(),number(m.get("set_count")),number(m.get("repetitions")),(BigDecimal)m.get("load_kg"))).toList();var details=json.readValue(p.get("equipment_details").toString(),new TypeReference<LinkedHashMap<String,Object>>(){});var authority=new LinkedHashMap<String,Object>();for(var key:List.of("exercise_option_id","exercise_type_id","recorded_date","duration_minutes","estimated_kj","estimate_status","weight_kg_used","weight_date_used","met_used","formula_version"))authority.put(key,p.get(key));String fp=canonical.hash("exercise-stored-period-v2",authority);UUID uuid=(UUID)p.get("client_entry_id");var duration=(BigDecimal)p.get("duration_minutes");var input=new Period(uuid,p.get("period_kind").toString(),p.get("exercise_option_id").toString(),duration,details,inputMoves,fp);ps.add(input);var status=EstimateStatus.valueOf(p.get("estimate_status").toString());String publicStatus=switch(status){case AVAILABLE->"AVAILABLE";case MISSING_WEIGHT->"NO_WEIGHT";case NO_APPLICABLE_REFERENCE->p.get("exercise_type_id")==null?"NO_APPLICABLE_REFERENCE":"UNSUPPORTED_REFERENCE";default->"UNSUPPORTED_REFERENCE";};var summary=new WorkoutEstimateService.PeriodPreview(uuid,duration,publicStatus,(BigDecimal)p.get("estimated_kj"),fp,status==EstimateStatus.AVAILABLE?null:"This stored activity has no available energy estimate ("+publicStatus+").");summaries.add(summary);minutes=minutes.add(duration);if(status==EstimateStatus.AVAILABLE){available++;energy=energy.add(summary.estimatedKj());}var estimate=p.get("exercise_type_id")==null?null:new ExerciseEstimateResponse(null,date(p.get("recorded_date")),duration,(BigDecimal)p.get("estimated_kj"),status,summary.unavailableReason(),(BigDecimal)p.get("weight_kg_used"),p.get("weight_date_used")==null?null:date(p.get("weight_date_used")),(BigDecimal)p.get("met_used"),(String)p.get("formula_version"),fp);historical.put(uuid,new WorkoutEstimateService.HistoricalPeriod(date(p.get("recorded_date")),Long.parseLong(input.optionId()),duration,estimate,summary,inputMoves.stream().map(m->Long.parseLong(m.catalogueId())).collect(java.util.stream.Collectors.toSet())));}
  UUID rootUuid=(UUID)row.get("client_entry_id");Entry entry=kind.equals("quick")?new Quick(rootUuid,ps.getFirst()):new Workout(rootUuid,row.get("title").toString(),ps,row.get("origin_workout_id")==null?null:row.get("origin_workout_id").toString());var fingerprints=summaries.stream().map(p->Map.of("clientEntryId",p.clientEntryId(),"calculationFingerprint",p.calculationFingerprint())).toList();var preview=new WorkoutEstimateService.Response(summaries,minutes,available==0?null:energy,available>0&&available<summaries.size(),canonical.hash("workout-calculation-v2",fingerprints),canonical.hash("exercise-stored-input-v2",entry));var root=new Root(Long.toString(id),((Number)row.get("version")).longValue(),date(row.get("recorded_date")),RecordSource.valueOf(row.get("source").toString()).canonical().name(),instant(row.get("created_at")),instant(row.get("updated_at")),entry,preview);return new State(root,row,periodRows,moves,historical);
 }
 public static String table(String kind){if("quick".equals(kind))return "exercise_record";if("workout".equals(kind))return "workout_record";throw BusinessException.invalid("kind","Choose a Quick activity or Workout.");}
 private static Long number(Object value){return value==null?null:((Number)value).longValue();}private static LocalDate date(Object value){return ((java.sql.Date)value).toLocalDate();}private static Instant instant(Object value){return ((java.sql.Timestamp)value).toInstant();}
 private static BusinessException missing(){return new BusinessException(HttpStatus.NOT_FOUND,"NOT_FOUND","Exercise entry not found.");}
}
